<template>
  <section class="page">
    <header class="hero"><div><p class="eyebrow">STORY AGENT · STAGE 8 · READ-ONLY DURABLE RELEASE IMPORT</p><h2>Durable Signed Release 导入检查</h2><p>验证外部持久化 release record 与 candidate decision、不可变 artifact manifest、发布权限、key、时间和 Ed25519 签名的绑定。</p></div><RouterLink to="/story/stage8-finalization-preflight">返回终局预检</RouterLink></header>
    <div class="truth"><strong>Verify ≠ Create ≠ Import ≠ Professional Pass</strong><span>authority registry 固定由仓库侧读取；请求不能自带 trust，不创建、不签署、不持久化。</span></div>
    <p v-if="errorMessage" class="error">{{ errorMessage }}</p>
    <template v-if="workspace && result">
      <section class="summary"><article><span>项目</span><b>75</b></article><article><span>Candidate Ready</span><b>{{ workspace.summary.finalization_candidate_ready_project_count }}</b></article><article><span>Active Authority</span><b>{{ workspace.summary.active_release_authority_count }}</b></article><article><span>Verification Ready</span><b>{{ workspace.summary.release_record_verification_ready_project_count }}</b></article><article><span>Imported Release</span><b>{{ workspace.summary.durable_signed_release_imported_count }}</b></article><article><span>Release / Pro Credit</span><b class="zero">0 / 0</b></article></section>
      <section class="registry"><div><p class="eyebrow">REPOSITORY-CONTROLLED AUTHORITY</p><h3>{{ workspace.authority_registry.registry_id }}</h3></div><div><span>{{ workspace.authority_registry.status }}</span><b>{{ workspace.authority_registry.active_authority_count }} active · {{ workspace.authority_registry.known_release_id_count }} known release IDs</b></div></section>
      <section class="toolbar"><label>固定项目<select v-model="selectedBenchmarkId" @change="reload"><option v-for="project in workspace.projects" :key="project.benchmark_id" :value="project.benchmark_id">{{ project.video_type }} · {{ project.benchmark_id }}</option></select></label><button :disabled="validating" @click="validate">{{ validating ? '校验中' : '仅验证导入记录' }}</button></section>
      <section class="editors"><article><header><h3>Finalization Decision v2</h3><button @click="copy(decisionRaw)">复制</button></header><textarea v-model="decisionRaw" aria-label="Stage 8 finalization decision JSON" spellcheck="false" /></article><article><header><h3>Durable Release Record v1</h3><button @click="copy(releaseRaw)">复制</button></header><textarea v-model="releaseRaw" aria-label="Stage 8 durable release record JSON" spellcheck="false" /></article></section>
      <section class="results"><article class="checks"><header><div><p class="eyebrow">FAIL-CLOSED IMPORT GATES</p><h3>{{ result.verification_ready ? '记录验签就绪（仍未导入）' : '外部 release record 未就绪' }}</h3></div><b>{{ passedChecks }}/{{ checkEntries.length }}</b></header><div><p v-for="[key,value] in checkEntries" :key="key"><i :class="value ? 'ok' : 'no'">{{ value ? '✓' : '×' }}</i>{{ label(key) }}</p></div></article><article class="issues"><p class="eyebrow">BLOCKING ISSUES</p><h3>{{ result.issues.length }} · imported=false · professional=false</h3><ul><li v-for="item in result.issues.slice(0,18)" :key="`${item.code}:${item.path}`"><b>{{ item.gate }}</b>{{ item.code }}</li></ul></article></section>
    </template>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { Stage8DurableReleaseInspectionResult, Stage8DurableReleaseWorkspace } from '@shared/types'
import { getStage8DurableReleaseWorkspace, validateStage8DurableRelease } from '../api/stage8-blind-review'
const workspace=ref<Stage8DurableReleaseWorkspace|null>(null),result=ref<Stage8DurableReleaseInspectionResult|null>(null),selectedBenchmarkId=ref(''),decisionRaw=ref(''),releaseRaw=ref(''),errorMessage=ref(''),validating=ref(false)
const checkEntries=computed(()=>Object.entries(result.value?.checks??{})),passedChecks=computed(()=>checkEntries.value.filter(([,value])=>value).length)
onMounted(()=>reload())
async function reload(){const response=await getStage8DurableReleaseWorkspace(selectedBenchmarkId.value);if(!response.ok||!response.data){errorMessage.value=response.error?.message??'durable release工作台加载失败';return}workspace.value=response.data;selectedBenchmarkId.value=response.data.selected_benchmark_id;decisionRaw.value=response.data.finalization_decision_template_raw_json;releaseRaw.value=response.data.release_record_template_raw_json;result.value=response.data.template_inspection}
async function validate(){validating.value=true;errorMessage.value='';try{const response=await validateStage8DurableRelease({expected_benchmark_id:selectedBenchmarkId.value,finalization_decision_raw_json:decisionRaw.value,release_record_raw_json:releaseRaw.value});if(!response.ok||!response.data){errorMessage.value=response.error?.message??'release record验证失败';return}result.value=response.data}finally{validating.value=false}}
async function copy(value:string){try{await navigator.clipboard.writeText(value)}catch{errorMessage.value='浏览器未授权复制'}}
const labels:Record<string,string>={request_valid:'请求完整',finalization_decision_json_valid:'Decision JSON',finalization_decision_schema_valid:'Decision v2 schema',finalization_decision_quality_gate_valid:'Decision质量增量',finalization_candidate_eligible:'Candidate资格',release_record_json_valid:'Release JSON',release_record_schema_valid:'Release v1 schema',benchmark_binding_valid:'Benchmark绑定',run_id_binding_valid:'Run绑定',video_type_binding_valid:'片型绑定',finalization_decision_digest_binding_valid:'Decision SHA-256',artifact_manifest_digest_valid:'Manifest SHA-256',artifact_manifest_identity_valid:'Manifest身份',artifact_manifest_immutable_shape_valid:'12件唯一artifact',artifact_manifest_required_records_bound:'三项关键记录入清单',authority_registry_schema_valid:'Authority registry',authority_registry_is_external:'外部trust来源',authority_binding_valid:'Authority scope绑定',authority_key_trusted:'Active key',release_id_unique:'Release ID唯一',issued_at_valid:'签发时间',expires_at_valid:'有效期限',signature_payload_digest_valid:'签名payload',cryptographic_signature_valid:'Ed25519验签',source_claimed_credit_rejected:'拒绝自报信用'}
function label(key:string){return labels[key]??key}
</script>

