lay:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #2b4c46}.editors h3,.checks h3,.issues h3{margin:3px 0}.editors textarea{width:100%;height:340px;padding:12px;box-sizing:border-box;resize:vertical;border:0;outline:0;color:#e7f1ef;background:#050c0b;font:9px/1.5 ui-monospace,SFMono-Regular,monospace}.checks>div{padding:10px;display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.checks p{margin:0;padding:8px;border-radius:6px;background:#19332e;font-size:8px}.checks i{margin-right:6px;font-style:normal}.ok{color:#86dfa9}.no{color:#ff9ba5}.issues{padding:13px}.issues ul{max-height:270px;margin:0;padding-left:0;overflow:auto;list-style:none;color:#d0dedb;font:9px/1.6 ui-monospace,monospace}.issues li{display:flex;gap:8px;padding:5px;border-bottom:1px solid #24423d}.issues li b{color:#ffad91}@media(max-width:1000px){.summary{grid-template-columns:repeat(3,1fr)}.editors,.results{grid-template-columns:1fr}.toolbar,.registry{align-items:flex-start;flex-direction:column}.toolbar select{min-width:0;width:100%}}@media(max-width:650px){.page{padding:18px 12px}.hero,.truth{align-items:flex-start;flex-direction:column}.summary,.checks>div{grid-template-columns:1fr}}
</style>
